// Turn the numbers into a short Telegram message (plain text, no names, no question text).
const s = $input.first().json;
const n = v => Number(v ?? 0).toLocaleString('en-US');
const people = v => `${n(v)} ${Number(v) === 1 ? 'person' : 'people'}`;
const day = new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
const lines = [
  `RAG health · ${day}`,
  '',
  `Library: ${n(s.files_searchable)} documents searchable · ${n(s.passages)} passages · ${n(s.images)} images · ${n(s.sheets)} spreadsheets`,
  `Last 24 h ingestion: ${n(s.ingested_24h)} processed · ${n(s.skipped_24h)} skipped · now failing: ${n(s.failing_now)} · retrying: ${n(s.retrying_now)}`,
  `Questions: ${n(s.questions_24h)} in 24 h (${people(s.people_24h)}) · ${n(s.questions_7d)} in 7 days (${people(s.people_7d)})`,
];
// ---- error flow (design part 11, generated by build_ops_workflows.daily_health) ----
// Four lines under "Questions": answers checked (real sessions only), unresolved incidents, the latest eval run per set,
// the latest backup. Counts and workflow/node names only; times in PT (an earlier day is named). Two warnings repeat in
// every digest until fixed, each naming its runbook section: a set below its floor (R96) and no backup for 36 h.
const EVAL_FLOORS = {"demo": 7, "messy": 10, "visual": 10};
const EVAL_OVERDUE_DAYS = 8;
const BACKUP_MAX_AGE_H = 36;
const num = (v) => { const x = Number(v); return v === null || v === undefined || !Number.isFinite(x) ? 0 : x; };
const obj = (v) => { if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return null; } }
                     return v !== null && typeof v === 'object' && !Array.isArray(v) ? v : null; };
const asDate = (v) => { if (v === null || v === undefined || v === '') return null; const d = new Date(v); return isNaN(d) ? null : d; };
const ptParts = (d) => Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Los_Angeles', year: 'numeric',
  weekday: 'short', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
  .formatToParts(d).map((x) => [x.type, x.value]));
const nowPt = ptParts(new Date());
const isToday = (p) => p.year === nowPt.year && p.month === nowPt.month && p.day === nowPt.day;
const clock = (v) => { const d = asDate(v); if (!d) return '?'; const p = ptParts(d); return `${isToday(p) ? '' : p.weekday + ' '}${p.hour}:${p.minute}`; };
// a run of the last 7 days is named by its weekday (Saturday's digest still says "Sun"), unless that weekday is today's
const dayOf = (d) => { const p = ptParts(d); return isToday(p) ? 'today'
  : Date.now() - d < 7 * 86400000 && p.weekday !== nowPt.weekday ? p.weekday : `${p.month} ${p.day}`; };
const sizeOf = (b) => { const x = num(b); return x <= 0 ? null : x >= 1073741824 ? `${(x / 1073741824).toFixed(1)} GB` : `${Math.round(x / 1048576)} MB`; };

const answersLine = (() => {
  if (num(s.answers_24h) === 0) return [true, 't', 'true'].includes(s.answers_ever) ? 'Answers: none in 24 h' : 'Answers: none checked yet';
  const parts = [`${n(s.answers_24h)} checked`, `${n(s.grounded_24h)} grounded`, `${n(s.partial_24h)} partial`,
                 `${n(s.unsupported_24h)} unsupported`];
  if (num(s.not_applicable_24h) > 0) parts.push(`${n(s.not_applicable_24h)} not applicable`);
  if (num(s.not_graded_24h) > 0) parts.push(`${n(s.not_graded_24h)} not graded`);
  parts.push(`${n(s.flagged_24h)} flagged "could not verify"`);
  return 'Answers: ' + parts.join(' · ');
})();

const incidentsLine = (() => {
  if (num(s.incidents_24h) === 0) return 'Incidents: none in 24 h';
  let t = `Incidents: ${n(s.incidents_24h)}` + (s.incidents_by_workflow ? ` (${s.incidents_by_workflow})` : '');
  const last = obj(s.last_incident);
  if (last) t += ` · last: ${clock(last.at)} ${last.label ?? '?'}` + (last.node ? ` "${last.node}"` : '');
  if (num(s.incidents_not_alerted) > 0) t += ` · ${n(s.incidents_not_alerted)} not alerted on Telegram`;
  return t;
})();

const evalsLine = (() => {
  const sets = Object.keys(EVAL_FLOORS).map((name) => ({ name, run: obj(s['eval_' + name]) }));
  if (!sets.some((x) => x.run)) return 'Evals: none yet';
  let warn = false;
  const parts = sets.map(({ name, run }) => {
    if (!run) return `${name} none yet`;
    const at = asDate(run.at);
    let t = `${name} ${n(run.passed)}/${n(run.total)} (${at ? dayOf(at) : '?'})`;
    if (num(run.passed) < EVAL_FLOORS[name]) { t += ' ⚠️ below floor'; warn = true; }
    if (!at || Date.now() - at > EVAL_OVERDUE_DAYS * 86400000) { t += ' ⚠️ overdue'; warn = true; }
    return t;
  });
  return 'Evals: ' + parts.join(' · ') + (warn ? ' · Runbook: Eval drop' : '');
})();

const backupLine = (() => {
  const at = asDate(s.backup_at);
  if (!at) return 'Backup: ⚠️ No backup recorded yet · Runbook: Backup failed';
  const sets = num(s.backup_sets);
  const ok = [`ok ${clock(at)}`, sizeOf(s.backup_bytes), sets > 0 ? `${n(sets)} ${sets === 1 ? 'set' : 'sets'} kept` : null]
    .filter(Boolean).join(' · ');
  const age = s.backup_age_h === null || s.backup_age_h === undefined ? (Date.now() - at) / 3600000 : num(s.backup_age_h);
  return age > BACKUP_MAX_AGE_H ? `Backup: ⚠️ No backup for ${Math.floor(age)} h (last ${ok}) · Runbook: Backup failed` : `Backup: ${ok}`;
})();
lines.push(answersLine, incidentsLine, evalsLine, backupLine);
// ---- end of error flow ----
if (Number(s.erasures_24h) > 0) lines.push(`Privacy: ${n(s.erasures_24h)} erasure request(s) carried out`);
if (Number(s.failing_now) > 0) lines.push('', 'Needs a look — still failing:', s.failures);
if (Number(s.retrying_now) > 0) lines.push('', 'Some files are retrying (temporary errors); they will be picked up on later runs.');
lines.push('', 'Spend: Azure emails you at 50% / 80% of your monthly budget.');
// Telegram parses formatting; send HTML with &, < and > escaped so file names (underscores etc.) can't break it
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = lines.map(esc);
out[0] = `<b>${out[0]}</b>`;
return [{ json: { text: out.join('\n') } }];
